# solution.py

"""
Team_Tactics - A multiplayer action game testing collaborative AI capabilities.

This module implements a game environment with multiple levels, AI agents with
different roles and abilities, a communication system, and a scoring system.
"""

import random
from typing import List, Dict, Tuple, Optional, Set
from enum import Enum
from abc import ABC, abstractmethod
import uuid


# ==================== ENUMS AND CONSTANTS ====================

class Objective(Enum):
    """Types of objectives in the game."""
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ELIMINATE_ENEMIES = "eliminate_enemies"


class Role(Enum):
    """Agent roles with specific responsibilities."""
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SCOUT = "scout"


class Ability(Enum):
    """Special abilities agents can possess."""
    INCREASED_SPEED = "increased_speed"
    HEALING = "healing"
    SHIELDING = "shielding"


class MessageType(Enum):
    """Types of messages agents can send."""
    ENEMY_LOCATION = "enemy_location"
    OBJECTIVE_STATUS = "objective_status"
    STRATEGIC_PLAN = "strategic_plan"
    REQUEST_HELP = "request_help"


# ==================== GAME ENVIRONMENT ====================

class Position:
    """Represents a position in the game grid."""

    def __init__(self, x: int, y: int):
        self.x = x
        self.y = y

    def distance_to(self, other: 'Position') -> float:
        """Calculate Euclidean distance to another position."""
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

    def move_towards(self, target: 'Position', max_distance: int = 1) -> 'Position':
        """Move towards target position with maximum step distance."""
        dx = target.x - self.x
        dy = target.y - self.y
        distance = self.distance_to(target)

        if distance <= max_distance:
            return target

        # Move proportionally towards target
        new_x = self.x + int((dx / distance) * max_distance)
        new_y = self.y + int((dy / distance) * max_distance)
        return Position(new_x, new_y)

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

    def __hash__(self):
        return hash((self.x, self.y))

    def __repr__(self):
        return f"Position({self.x}, {self.y})"


class Level:
    """Represents a game level with specific objectives and layout."""

    def __init__(self, level_id: int, objective: Objective, grid_size: Tuple[int, int]):
        self.level_id = level_id
        self.objective = objective
        self.grid_width, self.grid_height = grid_size
        self.agents: List['Agent'] = []
        self.enemies: List['Enemy'] = []
        self.flags: Dict[str, Position] = {}  # flag_id -> position
        self.bases: Dict[str, Position] = {}  # base_id -> position
        self.obstacles: Set[Position] = set()

        # Level-specific properties
        self._generate_environment()

    def _generate_environment(self):
        """Generate level-specific elements based on objective."""
        if self.objective == Objective.CAPTURE_FLAG:
            # Place flag in center, bases at opposite corners
            center = Position(self.grid_width // 2, self.grid_height // 2)
            self.flags["main_flag"] = center
            self.bases["team_base"] = Position(1, 1)
            self.bases["enemy_base"] = Position(self.grid_width - 2, self.grid_height - 2)

            # Add some obstacles
            for _ in range(5):
                x = random.randint(2, self.grid_width - 3)
                y = random.randint(2, self.grid_height - 3)
                if not (x == center.x and y == center.y):
                    self.obstacles.add(Position(x, y))

        elif self.objective == Objective.DEFEND_BASE:
            # Place base in center, enemies spawn around it
            center = Position(self.grid_width // 2, self.grid_height // 2)
            self.bases["main_base"] = center

            # Create defensive perimeter obstacles
            for x in range(center.x - 2, center.x + 3):
                for y in range(center.y - 2, center.y + 3):
                    if abs(x - center.x) == 2 or abs(y - center.y) == 2:
                        self.obstacles.add(Position(x, y))

        elif self.objective == Objective.ELIMINATE_ENEMIES:
            # Spread enemies throughout the level
            for i in range(5):
                x = random.randint(1, self.grid_width - 2)
                y = random.randint(1, self.grid_height - 2)
                self.enemies.append(Enemy(f"enemy_{i}", Position(x, y)))

            # Add random obstacles
            for _ in range(8):
                x = random.randint(0, self.grid_width - 1)
                y = random.randint(0, self.grid_height - 1)
                self.obstacles.add(Position(x, y))

    def is_valid_position(self, pos: Position) -> bool:
        """Check if position is within bounds and not obstructed."""
        return (0 <= pos.x < self.grid_width and 
                0 <= pos.y < self.grid_height and 
                pos not in self.obstacles)

    def get_nearby_agents(self, position: Position, radius: int = 3) -> List['Agent']:
        """Get agents within a certain radius of a position."""
        return [agent for agent in self.agents 
                if position.distance_to(agent.position) <= radius]

    def get_enemy_at_position(self, position: Position) -> Optional['Enemy']:
        """Get enemy at a specific position, if any."""
        for enemy in self.enemies:
            if enemy.position == position:
                return enemy
        return None

    def add_agent(self, agent: 'Agent'):
        """Add an agent to the level."""
        self.agents.append(agent)

    def remove_agent(self, agent: 'Agent'):
        """Remove an agent from the level."""
        if agent in self.agents:
            self.agents.remove(agent)

    def update(self):
        """Update level state (enemy movements, etc.)."""
        for enemy in self.enemies:
            if self.agents and random.random() < 0.3:  # 30% chance to move
                target = random.choice(self.agents)
                enemy.move_towards(target.position, self)


class Enemy:
    """Represents an enemy entity in the game."""

    def __init__(self, enemy_id: str, position: Position, health: int = 10):
        self.enemy_id = enemy_id
        self.position = position
        self.health = health
        self.is_alive = True

    def take_damage(self, damage: int):
        """Apply damage to the enemy."""
        self.health -= damage
        if self.health <= 0:
            self.is_alive = False

    def move_towards(self, target: Position, level: Level):
        """Move towards target position if possible."""
        new_pos = self.position.move_towards(target)
        if level.is_valid_position(new_pos):
            self.position = new_pos

    def __repr__(self):
        return f"Enemy({self.enemy_id}, pos={self.position}, health={self.health})"


# ==================== AI AGENTS ====================

class Message:
    """Represents a communication message between agents."""

    def __init__(self, sender: 'Agent', msg_type: MessageType, content: Dict, priority: int = 1):
        self.message_id = str(uuid.uuid4())
        self.sender = sender
        self.msg_type = msg_type
        self.content = content
        self.priority = priority  # 1=lowest, 5=highest
        self.timestamp = 0  # Will be set by communication system

    def __repr__(self):
        return f"Message({self.msg_type.value} from {self.sender.agent_id})"


class CommunicationSystem:
    """Manages communication between agents."""

    def __init__(self):
        self.messages: List[Message] = []
        self.message_history: Dict[str, List[Message]] = {}  # agent_id -> messages
        self.time = 0

    def send_message(self, message: Message):
        """Send a message to the communication system."""
        message.timestamp = self.time
        self.messages.append(message)

        # Store in sender's history
        sender_id = message.sender.agent_id
        if sender_id not in self.message_history:
            self.message_history[sender_id] = []
        self.message_history[sender_id].append(message)

        # Also store in history of nearby agents (simulating broadcast)
        nearby_agents = message.sender.level.get_nearby_agents(message.sender.position)
        for agent in nearby_agents:
            if agent.agent_id != sender_id:
                if agent.agent_id not in self.message_history:
                    self.message_history[agent.agent_id] = []
                self.message_history[agent.agent_id].append(message)

    def get_messages_for_agent(self, agent_id: str, msg_type: Optional[MessageType] = None) -> List[Message]:
        """Get messages for a specific agent, optionally filtered by type."""
        if agent_id not in self.message_history:
            return []

        messages = self.message_history[agent_id]
        if msg_type:
            messages = [msg for msg in messages if msg.msg_type == msg_type]

        # Sort by priority and timestamp
        messages.sort(key=lambda m: (-m.priority, m.timestamp))
        return messages

    def clear_old_messages(self, max_age: int = 10):
        """Clear messages older than max_age time units."""
        self.time += 1
        for agent_id in self.message_history:
            self.message_history[agent_id] = [
                msg for msg in self.message_history[agent_id]
                if self.time - msg.timestamp <= max_age
            ]


class Agent(ABC):
    """Base class for all AI agents."""

    def __init__(self, agent_id: str, role: Role, position: Position, 
                 abilities: List[Ability] = None):
        self.agent_id = agent_id
        self.role = role
        self.position = position
        self.abilities = abilities or []
        self.health = 100
        self.is_alive = True
        self.score = 0
        self.communication_system: Optional[CommunicationSystem] = None
        self.level: Optional[Level] = None

        # Agent state
        self.current_target: Optional[Position] = None
        self.inventory = {}

    def set_level(self, level: Level):
        """Set the level this agent is in."""
        self.level = level

    def set_communication_system(self, comm_system: CommunicationSystem):
        """Set the communication system for this agent."""
        self.communication_system = comm_system

    def take_damage(self, damage: int):
        """Apply damage to the agent."""
        if Ability.SHIELDING in self.abilities and random.random() < 0.5:
            damage = damage // 2  # 50% damage reduction with shielding

        self.health -= damage
        if self.health <= 0:
            self.is_alive = False
            if self.level:
                self.level.remove_agent(self)

    def heal(self, amount: int):
        """Heal the agent."""
        if Ability.HEALING in self.abilities:
            amount = int(amount * 1.5)  # 50% bonus healing

        self.health = min(100, self.health + amount)

    def move(self, target: Position):
        """Move towards a target position."""
        if not self.level or not self.is_alive:
            return

        speed = 2 if Ability.INCREASED_SPEED in self.abilities else 1
        new_position = self.position.move_towards(target, speed)

        if self.level.is_valid_position(new_position):
            self.position = new_position
            self.score += 1  # Small reward for movement
        else:
            # Try to find alternative path
            self._handle_obstacle()

    def _handle_obstacle(self):
        """Handle being stuck at an obstacle."""
        if self.communication_system:
            # Send help request
            msg = Message(
                self,
                MessageType.REQUEST_HELP,
                {"position": self.position, "reason": "stuck"},
                priority=3
            )
            self.communication_system.send_message(msg)

    def send_message(self, msg_type: MessageType, content: Dict, priority: int = 1):
        """Send a message through the communication system."""
        if self.communication_system:
            msg = Message(self, msg_type, content, priority)
            self.communication_system.send_message(msg)

    def receive_messages(self) -> List[Message]:
        """Receive messages from the communication system."""
        if self.communication_system:
            return self.communication_system.get_messages_for_agent(self.agent_id)
        return []

    @abstractmethod
    def decide_action(self):
        """Decide next action based on current situation."""
        pass

    def update(self):
        """Update agent state and decide next action."""
        if self.is_alive:
            self.decide_action()

            # Apply passive healing if ability present
            if Ability.HEALING in self.abilities and self.health < 100:
                self.heal(1)

    def __repr__(self):
        return f"Agent({self.agent_id}, {self.role.value}, pos={self.position}, health={self.health})"


class Attacker(Agent):
    """Attacker agent specialized in offensive operations."""

    def __init__(self, agent_id: str, position: Position, abilities: List[Ability] = None):
        super().__init__(agent_id, Role.ATTACKER, position, abilities)
        self.attack_power = 20
        self.attack_range = 2

    def decide_action(self):
        """Attacker decision logic."""
        if not self.level:
            return

        # Check for nearby enemies to attack
        for enemy in self.level.enemies:
            if enemy.is_alive and self.position.distance_to(enemy.position) <= self.attack_range:
                enemy.take_damage(self.attack_power)
                self.score += 10

                # Notify team about enemy
                self.send_message(
                    MessageType.ENEMY_LOCATION,
                    {"enemy_id": enemy.enemy_id, "position": enemy.position},
                    priority=2
                )

                if not enemy.is_alive:
                    self.score += 50  # Bonus for elimination
                return

        # Check for flag to capture
        if self.level.objective == Objective.CAPTURE_FLAG and self.level.flags:
            flag_pos = list(self.level.flags.values())[0]
            if self.position == flag_pos:
                self.score += 100  # Captured flag
                self.inventory["flag"] = True
                return
            else:
                self.current_target = flag_pos

        # Move towards current target or explore
        if self.current_target:
            self.move(self.current_target)
        else:
            # Explore randomly
            x = self.position.x + random.randint(-2, 2)
            y = self.position.y + random.randint(-2, 2)
            self.move(Position(max(0, min(x, self.level.grid_width - 1)),
                              max(0, min(y, self.level.grid_height - 1))))


class Defender(Agent):
    """Defender agent specialized in protecting objectives."""

    def __init__(self, agent_id: str, position: Position, abilities: List[Ability] = None):
        super().__init__(agent_id, Role.DEFENDER, position, abilities)
        self.defense_power = 15
        self.defense_range = 3

    def decide_action(self):
