            abilities.append(AgentAbility(AbilityType.MARK_TARGET, max_cooldown=4))
        elif self.role == AgentRole.DEFENDER:
            abilities.append(AgentAbility(AbilityType.SHIELDING, max_cooldown=6))
        elif self.role == AgentRole.SCOUT:
            abilities.append(AgentAbility(AbilityType.SPEED_BOOST, max_cooldown=2))
            abilities.append(AgentAbility(AbilityType.STEALTH, max_cooldown=5))
        elif self.role == AgentRole.MEDIC:
            abilities.append(AgentAbility(AbilityType.HEALING, max_cooldown=4))

        return abilities

    def move_towards(self, target: Position) -> None:
        """Move agent towards target position"""
        if not self.is_alive:
            return

        dx = target.x - self.position.x
        dy = target.y - self.position.y
        distance = math.sqrt(dx**2 + dy**2)

        if distance > 0:
            # Normalize and apply speed
            move_x = dx / distance * self.speed
            move_y = dy / distance * self.speed

            # Update position
            self.position.x += round(move_x)
            self.position.y += round(move_y)

    def use_ability(self, ability_type: AbilityType, target_agent: Optional['AIAgent'] = None) -> bool:
        """Use a specific ability"""
        for ability in self.abilities:
            if ability.ability_type == ability_type and ability.cooldown == 0:
                ability.cooldown = ability.max_cooldown
                ability.active = True
                ability.duration = 3  # Ability lasts for 3 turns

                # Apply ability effects
                if ability_type == AbilityType.SPEED_BOOST:
                    self.speed = self.base_speed * 2
                elif ability_type == AbilityType.HEALING and target_agent:
                    target_agent.heal(30)
                elif ability_type == AbilityType.SHIELDING:
                    # Shield prevents next damage
                    pass
                elif ability_type == AbilityType.MARK_TARGET and target_agent:
                    # Mark target for team to see
                    pass

                return True
        return False

    def take_damage(self, damage: int) -> None:
        """Take damage, checking for shielding ability"""
        # Check if shielding ability is active
        for ability in self.abilities:
            if ability.ability_type == AbilityType.SHIELDING and ability.active:
                ability.active = False
                return  # Shield absorbs all damage

        self.health -= damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0

    def heal(self, amount: int) -> None:
        """Heal the agent"""
        if self.is_alive:
            self.health = min(self.max_health, self.health + amount)

    def update_cooldowns(self) -> None:
        """Update cooldowns for all abilities"""
        for ability in self.abilities:
            if ability.cooldown > 0:
                ability.cooldown -= 1

            if ability.active:
                ability.duration -= 1
                if ability.duration <= 0:
                    ability.active = False
                    if ability.ability_type == AbilityType.SPEED_BOOST:
