        if not self.state.is_alive:
            return

        direction = target - self.state.position
        if direction.magnitude() > 0:
            move_distance = self.speed * delta_time
            move_vector = direction.normalized() * min(move_distance, direction.magnitude())
            self.state.position += move_vector

    def distance_to(self, position: Vector2) -> float:
        """Calculate distance to a position."""
        return self.state.position.distance_to(position)

    def can_see(self, other_position: Vector2) -> bool:
        """Check if robot can see another position within vision range."""
        return self.distance_to(other_position) <= self.vision_range

    def learn_from_experience(self, battle_result: Dict[str, Any]) -> None:
        """Learn from battle experience and adapt strategy."""
        # Store performance metrics
        self.strategy_memory['last_battle'] = {
            'kills': self.kills,
            'deaths': self.deaths,
            'assists': self.assists,
            'objective_score': self.objective_score,
            'result': battle_result.get('result', 'unknown')
        }

        # Simple adaptive learning: adjust aggression based on performance
        kd_ratio = self.kills / max(1, self.deaths)
        if kd_ratio < 0.5:
            # Be more defensive
            self.strategy_memory['aggression'] = max(0.1, self.strategy_memory.get('aggression', 0.5) - 0.1)
        elif kd_ratio > 2.0:
            # Be more aggressive
            self.strategy_memory['aggression'] = min(1.0, self.strategy_memory.get('aggression', 0.5) + 0.1)


