            'target': self.state.position,
            'attack_target': None,
            'use_power_up': False,
            'objective_priority': 0.6
        }

        # Find nearest enemy
        nearest_enemy = None
        min_distance = float('inf')

        for enemy in arena_state.enemy_positions:
            if self.can_see(enemy):
                distance = self.distance_to(enemy)
                if distance < min_distance:
                    min_distance = distance
                    nearest_enemy = enemy

        # Find nearest objective
        nearest_objective = None
        obj_distance = float('inf')

        for obj in arena_state.objective_positions:
            distance = self.distance_to(obj)
            if distance < obj_distance:
                obj_distance = distance
                nearest_objective = obj

        # Decision making
        if nearest_enemy and min_distance < 30:
            # Engage in close combat
            action['type'] = 'attack'
            action['attack_target'] = nearest_enemy
            action['target'] = nearest_enemy

            # Switch to melee if very close
            if min_distance < 3 and len(self.weapons) > 1:
                self.state.current_weapon_index = 1
            else:
                self.state.current_weapon_index = 0

        elif nearest_objective and obj_distance < 50:
            # Move towards objective
            action['target'] = nearest_objective
            action['objective_priority'] = 0.8

        elif nearest_enemy:
            # Move towards enemy
            action['target'] = nearest_enemy

        # Check if low health and retreat
        if self.state.health < 30:
            # Find nearest teammate for support
            nearest_teammate = None
            min_team_distance = float('inf')

            for teammate in team_states:
                if teammate.position != self.state.position:
