                    if distance < min_team_distance:
                        min_team_distance = distance
                        nearest_teammate = teammate.position

            if nearest_teammate:
                action['target'] = nearest_teammate
                action['objective_priority'] = 0.3

        return action


class DefenderAI(RobotAI):
