{
  "solution.py": "# solution.py
"""
CyberArena - A futuristic battle arena simulation with AI-controlled robots.
This system implements team-based challenges with real-time combat, adaptive AI,
and immersive environments.
"""

import random
import time
import math
from dataclasses import dataclass
from enum import Enum
from typing import List, Dict, Tuple, Optional, Any
from abc import ABC, abstractmethod
import numpy as np


# ==================== ENUMS AND DATA CLASSES ====================

class RobotClass(Enum):
    """Types of robot classes with different specialties."""
    ASSAULT = "Assault"
    DEFENSE = "Defense"
    SUPPORT = "Support"
    SCOUT = "Scout"


class WeaponType(Enum):
    """Types of weapons available to robots."""
    LASER_RIFLE = "Laser Rifle"
    PLASMA_CANNON = "Plasma Cannon"
    ENERGY_SWORD = "Energy Sword"
    ROCKET_LAUNCHER = "Rocket Launcher"
    MACHINE_GUN = "Machine Gun"
    SNIPER_RIFLE = "Sniper Rifle"


class ObjectiveType(Enum):
    """Types of team objectives."""
    CAPTURE_FLAG = "Capture Flag"
    DEFEND_BASE = "Defend Base"
    ESCORT_PAYLOAD = "Escort Payload"
    CONTROL_POINT = "Control Point"
    ELIMINATION = "Elimination"


class PowerUpType(Enum):
    """Types of power-ups available in the arena."""
    HEALTH_BOOST = "Health Boost"
    DAMAGE_BOOST = "Damage Boost"
    SPEED_BOOST = "Speed Boost"
    SHIELD = "Shield"
    INVISIBILITY = "Invisibility"
    AMMO_REFILL = "Ammo Refill"


@dataclass
class Vector2:
    """2D vector for positions and directions."""
    x: float
    y: float

    def __add__(self, other):
        return Vector2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2(self.x * scalar, self.y * scalar)

    def magnitude(self) -> float:
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag > 0:
            return Vector2(self.x / mag, self.y / mag)
        return Vector2(0, 0)

    def distance_to(self, other) -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)


@dataclass
class Weapon:
    """Weapon with stats and properties."""
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float
    ammo: int
    max_ammo: int
    is_melee: bool = False

    def can_fire(self) -> bool:
        return self.ammo > 0 and self.fire_rate > 0

    def fire(self):
        if self.ammo > 0:
            self.ammo -= 1
            return self.damage
        return 0.0


@dataclass
class PowerUp:
    """Power-up item in the arena."""
    position: Vector2
    power_type: PowerUpType
    duration: float
    value: float
    is_active: bool = True


@dataclass
class RobotState:
    """Current state of a robot."""
    position: Vector2
    health: float
    max_health: float
    shield: float
    energy: float
    weapon: Weapon
    robot_class: RobotClass
    team_id: int
    robot_id: int
    velocity: Vector2 = Vector2(0, 0)
    is_alive: bool = True
    active_power_ups: List[PowerUpType] = None
    last_action_time: float = 0.0

    def __post_init__(self):
        if self.active_power_ups is None:
            self.active_power_ups = []

    def take_damage(self, damage: float):
        """Apply damage to the robot, considering shield."""
        if self.shield > 0:
            shield_damage = min(damage, self.shield)
            self.shield -= shield_damage
            damage -= shield_damage

        self.health = max(0, self.health - damage)
        if self.health <= 0:
            self.is_alive = False

    def heal(self, amount: float):
        """Heal the robot."""
        self.health = min(self.max_health, self.health + amount)

    def add_power_up(self, power_type: PowerUpType):
        """Add a power-up effect."""
        if power_type not in self.active_power_ups:
            self.active_power_ups.append(power_type)

    def remove_power_up(self, power_type: PowerUpType):
        """Remove a power-up effect."""
        if power_type in self.active_power_ups:
            self.active_power_ups.remove(power_type)


@dataclass
class Objective:
    """Team objective in the arena."""
    position: Vector2
    objective_type: ObjectiveType
    progress: float = 0.0
    max_progress: float = 100.0
    controlling_team: Optional[int] = None
    is_completed: bool = False

    def update_progress(self, team_id: int, delta_progress: float):
        """Update objective progress for a team."""
        if self.is_completed:
            return

        if self.controlling_team is None or self.controlling_team == team_id:
            self.progress += delta_progress
            self.controlling_team = team_id
        else:
            self.progress -= delta_progress

        if self.progress <= 0:
            self.progress = 0
            self.controlling_team = None
        elif self.progress >= self.max_progress:
            self.progress = self.max_progress
            self.is_completed = True


@dataclass
class ArenaState:
    """Current state of the entire arena."""
    robots: List[RobotState]
    objectives: List[Objective]
    power_ups: List[PowerUp]
    time_elapsed: float
    team_scores: Dict[int, float]
    difficulty_level: float
    hazards: List[Vector2]

    def get_team_robots(self, team_id: int) -> List[RobotState]:
        """Get all robots belonging to a specific team."""
        return [robot for robot in self.robots if robot.team_id == team_id and robot.is_alive]

    def get_nearby_power_ups(self, position: Vector2, radius: float) -> List[PowerUp]:
        """Get power-ups within a radius of a position."""
        return [pu for pu in self.power_ups 
                if pu.is_active and position.distance_to(pu.position) <= radius]

    def get_nearby_hazards(self, position: Vector2, radius: float) -> List[Vector2]:
        """Get hazards within a radius of a position."""
        return [haz for haz in self.hazards 
                if position.distance_to(haz) <= radius]


# ==================== AI AGENT SYSTEM ====================

class AIAgent(ABC):
    """Abstract base class for AI agents controlling robots."""

    def __init__(self, robot_state: RobotState):
        self.state = robot_state
        self.strategy_memory: Dict[str, Any] = {}
        self.performance_score: float = 0

