                    )

            # Identify categories with highest expenses
            if user.expenses:
                expenses_by_category = {
                    cat: user.get_category_expenses(cat) for cat in ExpenseCategory
                }
                highest_category = max(expenses_by_category.items(), key=lambda x: x[1])
                if highest_category[1] > 0:
                    user_suggestions.append(
                        f"Consider reducing expenses in {highest_category[0].value} "
                        f"(current: ${highest_category[1]:.2f})"
                    )

            # Suggest reallocation if some categories have remaining budget
            remaining_budgets = user.get_all_remaining_budgets()
            positive_remaining = [(cat, rem) for cat, rem in remaining_budgets.items() 
                                 if rem is not None and rem > 0]
            negative_remaining = [(cat, rem) for cat, rem in remaining_budgets.items() 
                                 if rem is not None and rem < 0]

            if positive_remaining and negative_remaining:
                for pos_cat, pos_rem in positive_remaining:
                    for neg_cat, neg_rem in negative_remaining:
                        realloc_amount = min(pos_rem, -neg_rem)
                        if realloc_amount > 0:
