                for exp in self.expenses
            ],
            "category_limits": {
                cat.value: limit for cat, limit in self.category_limits.items()
            }
        }

    @classmethod
    def from_dict(cls, data: dict) -> 'UserBudget':
        """Create UserBudget object from dictionary."""
        user_budget = cls(username=data["username"])

        # Load expenses
        for exp_data in data.get("expenses", []):
            expense = Expense(
                amount=exp_data["amount"],
                category=ExpenseCategory(exp_data["category"]),
                description=exp_data["description"],
                date=exp_data.get("date", datetime.now().strftime("%Y-%m-%d"))
            )
            user_budget.expenses.append(expense)

        # Load category limits
        for cat_str, limit in data.get("category_limits", {}).items():
            user_budget.category_limits[ExpenseCategory(cat_str)] = limit

        return user_budget


class MultiAgentBudgetOptimizer:
    """Main class for managing multiple users' budgets and optimizing spending."""

    def __init__(self, data_file: str = "budget_data.json"):
        """
        Initialize the MultiAgentBudgetOptimizer.

        Args:
            data_file: Path to JSON file for persistent data storage
        """
        self.data_file = data_file
        self.users: Dict[str, UserBudget] = {}
        self.load_data()

    def add_user(self, username: str) -> bool:
        """
        Add a new user to the system.

        Args:
            username: Unique identifier for the user

        Returns:
            True if user was added successfully, False if user already exists
        """
        if username in self.users:
            return False
        self.users[username] = UserBudget(username=username)
        self.save_data()
        return True

    def record_expense(self, username: str, amount: float, category: ExpenseCategory, 
                      description: str = "") -> bool:
        """
        Record an expense for a specific user.

        Args:
            username: User recording the expense
            amount: Expense amount (must be positive)
            category: Expense category
            description: Optional description of the expense

        Returns:
            True if expense was recorded successfully, False if user doesn't exist
        """
        if username not in self.users:
            return False

        try:
            expense = Expense(
                amount=amount,
                category=category,
                description=description
            )
            self.users[username].add_expense(expense)
            self.save_data()
            return True
        except ValueError as e:
            print(f"Error recording expense: {e}")
            return False

    def set_budget_limit(self, username: str, category: ExpenseCategory, limit: float) -> bool:
        """
        Set budget limit for a user's category.

        Args:
            username: User to set limit for
            category: Expense category
            limit: Budget limit (must be non-negative)

        Returns:
            True if limit was set successfully, False if user doesn't exist
        """
        if username not in self.users:
            return False

        try:
            self.users[username].set_category_limit(category, limit)
            self.save_data()
            return True
        except ValueError as e:
            print(f"Error setting budget limit: {e}")
            return False

    def get_user_summary(self, username: str) -> Optional[dict]:
        """
        Get detailed summary for a specific user.

        Args:
            username: User to get summary for

        Returns:
            Dictionary with user's financial summary, or None if user doesn't exist
        """
        if username not in self.users:
            return None

        user = self.users[username]
        return {
            "username": username,
            "total_expenses": user.get_total_expenses(),
            "category_expenses": {
                cat.value: user.get_category_expenses(cat)
                for cat in ExpenseCategory
            },
            "category_limits": {
                cat.value: limit for cat, limit in user.category_limits.items()
            },
            "remaining_budgets": {
                cat.value: remaining
                for cat, remaining in user.get_all_remaining_budgets().items()
            },
            "over_budget_categories": [
                cat.value for cat in user.category_limits 
                if user.is_over_budget(cat)
            ]
        }

    def get_group_summary(self) -> dict:
        """
        Get summary of the entire group's financial status.

        Returns:
            Dictionary with group's financial summary
        """
        total_expenses = sum(user.get_total_expenses() for user in self.users.values())

        # Calculate category-wise totals
        category_totals = {cat.value: 0.0 for cat in ExpenseCategory}
        for user in self.users.values():
            for cat in ExpenseCategory:
                category_totals[cat.value] += user.get_category_expenses(cat)

        # Calculate individual contributions
        individual_contributions = {
            username: {
                "total": user.get_total_expenses(),
                "percentage": (user.get_total_expenses() / total_expenses * 100 
                              if total_expenses > 0 else 0)
            }
            for username, user in self.users.items()
        }

        return {
            "total_users": len(self.users),
            "total_group_expenses": total_expenses,
            "category_totals": category_totals,
            "individual_contributions": individual_contributions,
            "average_expense_per_user": total_expenses / len(self.users) if self.users else 0
        }

    def optimize_spending(self) -> Dict[str, List[str]]:
        """
        Generate optimization suggestions for all users.

        Returns:
            Dictionary mapping usernames to list of optimization suggestions
        """
        suggestions = {}

        for username, user in self.users.items():
            user_suggestions = []

            # Check for over-budget categories
            for category in user.category_limits:
                if user.is_over_budget(category):
                    overspend = -user.get_remaining_budget(category)
                    user_suggestions.append(
                        f"Reduce {category.value} spending by ${overspend:.2f} to stay within budget"
                    )

            # Identify categories with highest expenses
            if user.expenses:
                expenses_by_category = {
                    cat: user.get_category_expenses(cat) for cat in ExpenseCategory
                }
                highest_category = max(expenses_by_category.items(), key=lambda x: x[1])
                if highest_category[1] > 0:
                    user_suggestions.append(
                        f"Consider reducing expenses in {highest_category[0].value} "
                        f"(current: ${highest_category[1]:.2f})"
                    )

            # Suggest reallocation if some categories have remaining budget
            remaining_budgets = user.get_all_remaining_budgets()
            positive_remaining = [(cat, rem) for cat, rem in remaining_budgets.items() 
                                 if rem is not None and rem > 0]
            negative_remaining = [(cat, rem) for cat, rem in remaining_budgets.items() 
                                 if rem is not None and rem < 0]

            if positive_remaining and negative_remaining:
                for pos_cat, pos_rem in positive_remaining:
                    for neg_cat, neg_rem in negative_remaining:
                        realloc_amount = min(pos_rem, -neg_rem)
                        if realloc_amount > 0:
                            user_suggestions.append(
                                f"Consider reallocating ${realloc_amount:.2f} from "
                                f"{pos_cat.value} to {neg_cat.value}"
                            )

            if user_suggestions:
                suggestions[username] = user_suggestions

        return suggestions

    def save_data(self) -> None:
        """Save all user data to JSON file."""
        data = {
            "users": {
                username: user.to_dict()
                for username, user in self.users.items()
            }
        }

        try:
            with open(self.data_file, 'w') as f:
                json.dump(data, f, indent=2)
        except IOError as e:
            print(f"Error saving data: {e}")

    def load_data(self) -> None:
        """Load user data from JSON file."""
        try:
            with open(self.data_file, 'r') as f:
                data = json.load(f)

            self.users = {
                username: UserBudget.from_dict(user_data)
                for username, user_data in data.get("users", {}).items()
            }
        except FileNotFoundError:
            # File doesn't exist yet, start with empty users
            self.users = {}
        except (json.JSONDecodeError, KeyError) as e:
            print(f"Error loading data: {e}")
            self.users = {}

    def display_dashboard(self) -> None:
        """Display a comprehensive dashboard of group and individual financial status."""
        print("\n" + "="*60)
        print("MULTI-AGENT BUDGET OPTIMIZER DASHBOARD")
        print("="*60)

        # Group Summary
        group_summary = self.get_group_summary()
        print(f"\nGROUP SUMMARY:")
        print(f"  Total Users: {group_summary['total_users']}")
        print(f"  Total Group Expenses: ${group_summary['total_group_expenses']:.2f}")
        print(f"  Average Expense per User: ${group_summary['average_expense_per_user']:.2f}")

        print(f"\n  Category-wise Totals:")
        for category, total in group_summary['category_totals'].items():
            if total > 0:
                print(f"    {category.title()}: ${total:.2f}")

        print(f"\n  Individual Contributions:")
        for username, contribution in group_summary['individual_contributions'].items():
            print(f"    {username}: ${contribution['total']:.2f} "
                  f"({contribution['percentage']:.1f}%)")

        # Individual Summaries
        print(f"\nINDIVIDUAL SUMMARIES:")
        for username in self.users:
            user_summary = self.get_user_summary(username)
            if user_summary:
                print(f"\n  User: {username}")
                print(f"    Total Expenses: ${user_summary['total_expenses']:.2f}")

                if user_summary['category_limits']:
                    print(f"    Budget Status:")
                    for category in user_summary['remaining_budgets']:
                        remaining = user_summary['remaining_budgets'][category]
                        if remaining is not None:
                            status = "OVER" if remaining < 0 else "OK"
                            print(f"      {category.title()}: ${abs(remaining):.2f} {status}")

        # Optimization Suggestions
        suggestions = self.optimize_spending()
        if suggestions:
            print(f"\nOPTIMIZATION SUGGESTIONS:")
            for username, user_suggestions in suggestions.items():
                print(f"\n  For {username}:")
                for suggestion in user_suggestions:
                    print(f"    • {suggestion}")

        print("\n" + "="*60)


