import json
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field, asdict
from enum import Enum
from datetime import datetime


class ExpenseCategory(Enum):
    """Enumeration of possible expense categories."""
    GROCERIES = "groceries"
    ENTERTAINMENT = "entertainment"
    UTILITIES = "utilities"
    TRANSPORTATION = "transportation"
    DINING = "dining"
    SHOPPING = "shopping"
    OTHER = "other"


@dataclass
class Expense:
    """Data class representing a single expense entry."""
    amount: float
    category: ExpenseCategory
    description: str
    date: str = field(default_factory=lambda: datetime.now().strftime("%Y-%m-%d"))

    def __post_init__(self):
        """Validate expense data after initialization."""
        if self.amount <= 0:
            raise ValueError("Expense amount must be positive")
        if not isinstance(self.category, ExpenseCategory):
            self.category = ExpenseCategory(self.category)


@dataclass
class UserBudget:
    """Data class representing a user's budget and expenses."""
    username: str
    expenses: List[Expense] = field(default_factory=list)
    category_limits: Dict[ExpenseCategory, float] = field(default_factory=dict)

    def add_expense(self, expense: Expense) -> None:
        """Add an expense to the user's record."""
        self.expenses.append(expense)

    def set_category_limit(self, category: ExpenseCategory, limit: float) -> None:
        """Set budget limit for a specific category."""
        if limit < 0:
            raise ValueError("Budget limit cannot be negative")
        self.category_limits[category] = limit

    def get_total_expenses(self) -> float:
        """Calculate total expenses for the user."""
        return sum(expense.amount for expense in self.expenses)

    def get_category_expenses(self, category: ExpenseCategory) -> float:
        """Calculate expenses for a specific category."""
        return sum(exp.amount for exp in self.expenses if exp.category == category)

    def get_remaining_budget(self, category: ExpenseCategory) -> Optional[float]:
        """Calculate remaining budget for a category, or None if no limit set."""
        if category not in self.category_limits:
            return None
        return self.category_limits[category] - self.get_category_expenses(category)

    def get_all_remaining_budgets(self) -> Dict[ExpenseCategory, Optional[float]]:
        """Get remaining budget for all categories with limits."""
        return {cat: self.get_remaining_budget(cat) for cat in self.category_limits}

    def is_over_budget(self, category: ExpenseCategory) -> bool:
        """Check if user is over budget for a specific category."""
        remaining = self.get_remaining_budget(category)
        return remaining is not None and remaining < 0

    def to_dict(self) -> dict:
        """Convert UserBudget object to dictionary for serialization."""
        return {
            "username": self.username,
            "expenses": [
                {
                    "amount": exp.amount,
                    "category": exp.category.value,
                    "description": exp.description,
                    "date": exp.date
                }
                for exp in self.expenses
            ],
            "category_limits": {
                cat.value: limit for cat, limit in self.category_limits.items()
            }
        }

    @classmethod
    def from_dict(cls, data: dict) -> 'UserBudget':
        """Create UserBudget object from dictionary."""
        user_budget = cls(username=data["username"])

        # Load expenses
        for exp_data in data.get("expenses", []):
            expense = Expense(
                amount=exp_data["amount"],
                category=ExpenseCategory(exp_data["category"]),
                description=exp_data["description"],
                date=exp_data.get("date", datetime.now().strftime("%Y-%m-%d"))
            )
            user_budget.expenses.append(expense)

        # Load category limits
        for cat_str, limit in data.get("category_limits", {}).items():
            user_budget.category_limits[ExpenseCategory(cat_str)] = limit

        return user_budget


class MultiAgentBudgetOptimizer:
    """Main class for managing multiple users' budgets and optimizing spending."""

    def __init__(self, data_file: str = "budget_data.json"):
