    def record_expense(self, username: str, amount: float, category: ExpenseCategory, 
                      description: str = "") -> bool:
        """
        Record an expense for a specific user.

        Args:
            username: User recording the expense
            amount: Expense amount (must be positive)
            category: Expense category
            description: Optional description of the expense

        Returns:
            True if expense was recorded successfully, False if user doesn't exist
        """
        if username not in self.users:
            return False

        try:
            expense = Expense(
                amount=amount,
                category=category,
                description=description
            )
            self.users[username].add_expense(expense)
