import json
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field, asdict
from enum import Enum
from datetime import datetime


class ExpenseCategory(Enum):
    """Enumeration of possible expense categories."""
    GROCERIES = "groceries"
    ENTERTAINMENT = "entertainment"
    UTILITIES = "utilities"
    TRANSPORTATION = "transportation"
    DINING = "dining"
    SHOPPING = "shopping"
    OTHER = "other"


@dataclass
class Expense:
    """Data class representing a single expense."""
    id: str
    user_id: str
    amount: float
    category: ExpenseCategory
    description: str
    date: str

    def to_dict(self) -> dict:
        """Convert expense to dictionary."""
        return {
            "id": self.id,
            "user_id": self.user_id,
            "amount": self.amount,
            "category": self.category.value,
            "description": self.description,
            "date": self.date
        }


@dataclass
class User:
    """Data class representing a user."""
    id: str
    name: str
    email: str
    expenses: List[Expense] = field(default_factory=list)

    def add_expense(self, expense: Expense) -> None:
        """Add an expense to the user's expense list."""
        self.expenses.append(expense)

    def get_total_expenses(self) -> float:
        """Calculate total expenses for this user."""
        return sum(expense.amount for expense in self.expenses)

    def get_category_expenses(self, category: ExpenseCategory) -> float:
        """Calculate expenses for a specific category."""
        return sum(expense.amount for expense in self.expenses 
                   if expense.category == category)

    def to_dict(self) -> dict:
        """Convert user to dictionary."""
        return {
            "id": self.id,
            "name": self.name,
            "email": self.email,
            "expenses": [expense.to_dict() for expense in self.expenses]
        }


@dataclass
class BudgetLimit:
    """Data class representing budget limits for categories."""
    category: ExpenseCategory
    limit: float

    def to_dict(self) -> dict:
        """Convert budget limit to dictionary."""
        return {
            "category": self.category.value,
            "limit": self.limit
        }


class MultiAgentBudgetOptimizer:
    """Main class for the budget optimization application."""

    def __init__(self):
        self.users: Dict[str, User] = {}
        self.budget_limits: Dict[ExpenseCategory, BudgetLimit] = {}
        self.group_goals: List[str] = []

    def add_user(self, user_id: str, name: str, email: str) -> bool:
        """Add a new user to the system."""
        if user_id in self.users:
            return False
        self.users[user_id] = User(user_id, name, email)
        return True

    def remove_user(self, user_id: str) -> bool:
        """Remove a user from the system."""
        if user_id not in self.users:
            return False
        del self.users[user_id]
        return True

    def add_expense(self, user_id: str, expense_id: str, amount: float, 
                    category: ExpenseCategory, description: str) -> bool:
        """Add an expense for a specific user."""
        if user_id not in self.users:
            return False
        if amount <= 0:
            return False

        expense = Expense(
            id=expense_id,
            user_id=user_id,
            amount=amount,
            category=category,
            description=description,
            date=datetime.now().strftime("%Y-%m-%d")
        )

        self.users[user_id].add_expense(expense)
        return True

    def set_budget_limit(self, category: ExpenseCategory, limit: float) -> None:
        """Set budget limit for a specific category."""
        if limit < 0:
            raise ValueError("Budget limit cannot be negative")
        self.budget_limits[category] = BudgetLimit(category, limit)

    def adjust_budget_limit(self, category: ExpenseCategory, new_limit: float) -> bool:
        """Adjust existing budget limit for a category."""
        if category not in self.budget_limits:
            return False
        if new_limit < 0:
            raise ValueError("Budget limit cannot be negative")
        self.budget_limits[category].limit = new_limit
        return True

    def get_group_total_expenses(self) -> float:
        """Calculate total expenses for all users."""
        return sum(user.get_total_expenses() for user in self.users.values())

    def get_group_category_expenses(self, category: ExpenseCategory) -> float:
        """Calculate total expenses for a specific category across all users."""
        return sum(user.get_category_expenses(category) for user in self.users.values())

    def get_remaining_budget(self, category: ExpenseCategory) -> Optional[float]:
        """Calculate remaining budget for a category."""
        if category not in self.budget_limits:
            return None

        limit = self.budget_limits[category].limit
        expenses = self.get_group_category_expenses(category)
        return max(0, limit - expenses)

    def get_dashboard_summary(self) -> dict:
        """Generate dashboard summary for the group."""
        summary = {
            "total_users": len(self.users),
            "total_expenses": self.get_group_total_expenses(),
            "category_summary": {},
            "individual_contributions": {},
            "budget_status": {}
        }

        # Category summary
        for category in ExpenseCategory:
            category_expenses = self.get_group_category_expenses(category)
            summary["category_summary"][category.value] = category_expenses

            # Budget status
            remaining = self.get_remaining_budget(category)
            if remaining is not None:
                limit = self.budget_limits[category].limit
                status = {
                    "limit": limit,
                    "spent": category_expenses,
                    "remaining": remaining,
                    "percentage_used": (category_expenses / limit * 100) if limit > 0 else 0
                }
                summary["budget_status"][category.value] = status

        # Individual contributions
        for user_id, user in self.users.items():
            summary["individual_contributions"][user_id] = {
