// server.js - Main backend server file
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const http = require('http');
const socketIo = require('socket.io');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const axios = require('axios');

// Initialize Express app
const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
    cors: {
        origin: "http://localhost:3000",
        methods: ["GET", "POST"]
    }
});

// Middleware
app.use(cors());
app.use(express.json());

// Database connection
mongoose.connect('mongodb://localhost:27017/culturalconnect', {
    useNewUrlParser: true,
    useUnifiedTopology: true
});

// MongoDB Schemas
const userSchema = new mongoose.Schema({
    username: { type: String, required: true, unique: true },
    email: { type: String, required: true, unique: true },
    password: { type: String, required: true },
    preferences: {
        literature: [String],
        music: [String],
        visualArts: [String],
        films: [String],
        cultures: [String]
    },
    interactions: [{
        contentId: String,
        contentType: String,
        interactionType: String,
        timestamp: Date
    }],
    createdAt: { type: Date, default: Date.now }
});

const contentSchema = new mongoose.Schema({
    title: String,
    type: { type: String, enum: ['literature', 'music', 'visualArts', 'film', 'culturalFact'] },
    description: String,
    culture: String,
    mediaUrl: String,
    tags: [String],
    likes: { type: Number, default: 0 },
    shares: { type: Number, default: 0 },
    createdAt: { type: Date, default: Date.now }
});

const chatSchema = new mongoose.Schema({
    participants: [{ type: mongoose.Schema.Types.ObjectId, ref: 'User' }],
    messages: [{
        sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
        content: String,
        timestamp: { type: Date, default: Date.now }
    }]
});

// MongoDB Models
const User = mongoose.model('User', userSchema);
const Content = mongoose.model('Content', contentSchema);
const Chat = mongoose.model('Chat', chatSchema);

// JWT Secret
const JWT_SECRET = 'culturalconnect_secret_key';

// Authentication Middleware
const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) return res.sendStatus(401);

    jwt.verify(token, JWT_SECRET, (err, user) => {
        if (err) return res.sendStatus(403);
        req.user = user;
        next();
    });
};

// API Routes

// User Registration
app.post('/api/register', async (req, res) => {
    try {
        const { username, email, password } = req.body;

        // Check if user exists
        const existingUser = await User.findOne({ $or: [{ email }, { username }] });
        if (existingUser) {
            return res.status(400).json({ error: 'User already exists' });
        }

        // Hash password
        const hashedPassword = await bcrypt.hash(password, 10);

        // Create new user
        const user = new User({
            username,
            email,
            password: hashedPassword,
            preferences: {
                literature: [],
                music: [],
                visualArts: [],
                films: [],
                cultures: []
            }
        });

        await user.save();

        // Create JWT token
        const token = jwt.sign({ userId: user._id, username: user.username }, JWT_SECRET);

        res.status(201).json({ token, user: { username, email } });
    } catch (error) {
        res.status(500).json({ error: 'Registration failed' });
    }
});

// User Login
app.post('/api/login', async (req, res) => {
    try {
        const { email, password } = req.body;

        // Find user
        const user = await User.findOne({ email });
        if (!user) {
            return res.status(401).json({ error: 'Invalid credentials' });
        }

        // Check password
        const validPassword = await bcrypt.compare(password, user.password);
        if (!validPassword) {
            return res.status(401).json({ error: 'Invalid credentials' });
        }

        // Create JWT token
        const token = jwt.sign({ userId: user._id, username: user.username }, JWT_SECRET);

        res.json({ 
            token, 
            user: { 
                username: user.username, 
                email: user.email,
                preferences: user.preferences
            } 
        });
    } catch (error) {
        res.status(500).json({ error: 'Login failed' });
    }
});

// Get User Dashboard
app.get('/api/dashboard', authenticateToken, async (req, res) => {
    try {
        const user = await User.findById(req.user.userId);

        // Get recommendations based on user preferences
        const recommendations = await getRecommendations(user);

        // Get recent content
        const recentContent = await Content.find()
            .sort({ createdAt: -1 })
            .limit(10);

        res.json({
            user: {
                username: user.username,
                preferences: user.preferences
            },
            recommendations,
            recentContent,
            stats: {
                totalInteractions: user.interactions.length,
                culturesExplored: [...new Set(user.interactions.map(i => i.culture))].length
            }
        });
    } catch (error) {
        res.status(500).json({ error: 'Failed to load dashboard' });
    }
});

// Cultural Content API
app.get('/api/content', async (req, res) => {
    try {
        const { type, culture, page = 1, limit = 20 } = req.query;
        const query = {};

        if (type) query.type = type;
        if (culture) query.culture = culture;

        const content = await Content.find(query)
            .skip((page - 1) * limit)
            .limit(parseInt(limit))
            .sort({ likes: -1, createdAt: -1 });

        const total = await Content.countDocuments(query);

        res.json({
            content,
            pagination: {
                page: parseInt(page),
                limit: parseInt(limit),
                total,
                pages: Math.ceil(total / limit)
            }
        });
    } catch (error) {
        res.status(500).json({ error: 'Failed to fetch content' });
    }
});

// Add Cultural Content
app.post('/api/content', authenticateToken, async (req, res) => {
    try {
        const content = new Content({
            ...req.body,
            userId: req.user.userId
        });

        await content.save();

        // Record interaction
        await User.findByIdAndUpdate(req.user.userId, {
            $push: {
                interactions: {
                    contentId: content._id,
                    contentType: content.type,
                    interactionType: 'created',
                    timestamp: new Date()
                }
            }
        });

        res.status(201).json(content);
    } catch (error) {
        res.status(500).json({ error: 'Failed to create content' });
    }
});

// Update User Preferences
app.put('/api/preferences', authenticateToken, async (req, res) => {
    try {
        const { preferences } = req.body;

        await User.findByIdAndUpdate(req.user.userId, {
            $set: { preferences }
        });

        res.json({ message: 'Preferences updated successfully' });
    } catch (error) {
        res.status(500).json({ error: 'Failed to update preferences' });
    }
});

// External Cultural API Integration
app.get('/api/external/cultural-facts', async (req, res) => {
    try {
        // Example integration with external API
        const response = await axios.get('https://api.culturaldata.org/facts', {
            params: {
                limit: 10,
                category: req.query.category
            }
        });

        res.json(response.data);
    } catch (error) {
        res.status(500).json({ error: 'Failed to fetch cultural facts' });
    }
});

// Recommendation System Logic
async function getRecommendations(user) {
    try {
        const { preferences, interactions } = user;

        // Combine preferences and interaction history
        const allTags = [
            ...preferences.literature,
            ...preferences.music,
            ...preferences.visualArts,
            ...preferences.films,
            ...preferences.cultures,
            ...interactions.map(i => i.contentType)
        ];

        // Find content with matching tags
        const recommendations = await Content.find({
            $or: [
                { tags: { $in: allTags } },
                { culture: { $in: preferences.cultures } },
                { type: { $in: [
                    ...preferences.literature.length > 0 ? ['literature'] : [],
                    ...preferences.music.length > 0 ? ['music'] : [],
                    ...preferences.visualArts.length > 0 ? ['visualArts'] : [],
                    ...preferences.films.length > 0 ? ['film'] : []
                ] } }
            ]
        })
        .limit(10)
        .sort({ likes: -1 });

        return recommendations;
    } catch (error) {
        console.error('Recommendation error:', error);
        return [];
    }
}

// WebSocket Chat Implementation
const activeUsers = new Map();

io.on('connection', (socket) => {
    console.log('New user connected:', socket.id);

    socket.on('join', async (userId) => {
        activeUsers.set(socket.id, userId);
        socket.join(`user_${userId}`);
    });

    socket.on('private_message', async (data) => {
        const { recipientId, content } = data;
        const senderId = activeUsers.get(socket.id);

        if (!senderId || !recipientId) return;

        try {
            // Find or create chat
            let chat = await Chat.findOne({
                participants: { $all: [senderId, recipientId] }
            });

            if (!chat) {
                chat = new Chat({
                    participants: [senderId, recipientId],
                    messages: []
                });
            }

            // Add message
            chat.messages.push({
                sender: senderId,
                content,
                timestamp: new Date()
            });

            await chat.save();

            // Emit to recipient
            io.to(`user_${recipientId}`).emit('new_message', {
                senderId,
                content,
                timestamp: new Date()
            });

            // Emit to sender
            socket.emit('message_sent', {
                recipientId,
                content,
                timestamp: new Date()
            });
        } catch (error) {
            console.error('Chat error:', error);
        }
    });

    socket.on('get_chat_history', async (data) => {
        const { otherUserId } = data;
        const userId = activeUsers.get(socket.id);

        try {
            const chat = await Chat.findOne({
                participants: { $all: [userId, otherUserId] }
            }).populate('messages.sender', 'username');

            socket.emit('chat_history', chat ? chat.messages : []);
        } catch (error) {
            console.error('Chat history error:', error);
        }
    });

    socket.on('disconnect', () => {
        activeUsers.delete(socket.id);
        console.log('User disconnected:', socket.id);
    });
});

// Start server
const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
