# Database models
class User:
    def __init__(self, username, email, password_hash, preferences=None):
        self.id = hashlib.md5(email.encode()).hexdigest()[:12]
        self.username = username
        self.email = email
        self.password_hash = password_hash
        self.preferences = preferences or {"literature": [], "music": [], "art": [], "films": []}
        self.created_at = datetime.now().isoformat()

    def to_dict(self):
        return {
            "id": self.id,
            "username": self.username,
            "email": self.email,
            "preferences": self.preferences,
            "created_at": self.created_at
        }

class CulturalContent:
    def __init__(self, title, description, content_type, culture, media_url=None, facts=None):
        self.id = hashlib.md5(f"{title}{content_type}{culture}".encode()).hexdigest()[:12]
        self.title = title
        self.description = description
        self.content_type = content_type  # literature, music, art, film
        self.culture = culture
        self.media_url = media_url
        self.facts = facts or []
        self.likes = 0
        self.comments = []

    def to_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description,
            "content_type": self.content_type,
            "culture": self.culture,
            "media_url": self.media_url,
            "facts": self.facts,
            "likes": self.likes,
            "comments": self.comments
        }

# Database simulation
class Database:
    def __init__(self):
        self.users = {}
        self.content = {}
        self.sessions = {}

    def create_user(self, username, email, password):
        if email in [u.email for u in self.users.values()]:
            return None
        password_hash = hashlib.sha256(password.encode()).hexdigest()
        user = User(username, email, password_hash)
        self.users[user.id] = user
        return user

    def authenticate_user(self, email, password):
        password_hash = hashlib.sha256(password.encode()).hexdigest()
        for user in self.users.values():
            if user.email == email and user.password_hash == password_hash:
                return user
        return None

    def create_session(self, user_id):
        session_token = secrets.token_urlsafe(32)
        self.sessions[session_token] = {
            "user_id": user_id,
            "created_at": datetime.now().isoformat()
        }
        return session_token

    def validate_session(self, session_token):
        return self.sessions.get(session_token)

    def add_content(self, content):
        self.content[content.id] = content
        return content

    def get_content_by_type(self, content_type):
        return [c.to_dict() for c in self.content.values() if c.content_type == content_type]

    def get_content_by_culture(self, culture):
        return [c.to_dict() for c in self.content.values() if c.culture.lower() == culture.lower()]

    def search_content(self, query):
        query = query.lower()
        results = []
        for content in self.content.values():
            if (query in content.title.lower() or 
                query in content.description.lower() or
                query in content.culture.lower() or
                query in content.content_type.lower()):
                results.append(content.to_dict())
        return results

    def update_user_preferences(self, user_id, content_type, item_id):
        if user_id in self.users:
            user = self.users[user_id]
            if content_type in user.preferences:
                if item_id not in user.preferences[content_type]:
                    user.preferences[content_type].append(item_id)
                    return True
        return False

# Recommendation system
class RecommendationEngine:
    def __init__(self, db):
        self.db = db

    def get_recommendations(self, user_id):
        recommendations = []
        if user_id in self.db.users:
            user = self.db.users[user_id]

            # Content-based recommendations
            for content_type, liked_items in user.preferences.items():
                if liked_items:
                    # Get similar content (same type or culture)
                    for content in self.db.content.values():
                        if content.id not in liked_items and content.content_type == content_type:
                            recommendations.append(content.to_dict())
                            if len(recommendations) >= 10:
                                break

            # If not enough recommendations, add popular content
            if len(recommendations) < 5:
                popular = sorted(self.db.content.values(), key=lambda x: x.likes, reverse=True)[:10]
                for content in popular:
                    if content.to_dict() not in recommendations:
                        recommendations.append(content.to_dict())

        return recommendations[:10]

