mongoose.connect(process.env.MONGODB_URI || 'mongodb://localhost:27017/culturalconnect', {
    useNewUrlParser: true,
    useUnifiedTopology: true
});

// MongoDB Models
const User = mongoose.model('User', {
    username: { type: String, required: true, unique: true },
    email: { type: String, required: true, unique: true },
    password: { type: String, required: true },
    preferences: {
        literature: [String],
        music: [String],
        visualArts: [String],
        films: [String],
        cultures: [String]
    },
    interactions: [{
        contentId: String,
        contentType: String,
        interactionType: String,
        timestamp: Date
    }],
    createdAt: { type: Date, default: Date.now }
});

const CulturalContent = mongoose.model('CulturalContent', {
    title: String,
    description: String,
    type: { type: String, enum: ['literature', 'music', 'visualArts', 'film', 'educational'] },
    category: String,
    culture: String,
    mediaUrl: String,
    thumbnailUrl: String,
    facts: [String],
    tags: [String],
    likes: { type: Number, default: 0 },
    shares: { type: Number, default: 0 },
    createdAt: { type: Date, default: Date.now }
});

const ChatMessage = mongoose.model('ChatMessage', {
    senderId: mongoose.Schema.Types.ObjectId,
    receiverId: mongoose.Schema.Types.ObjectId,
    content: String,
    contentType: { type: String, default: 'text' },
    timestamp: { type: Date, default: Date.now }
});

// Authentication Middleware
const authMiddleware = async (req, res, next) => {
    try {
        const token = req.header('Authorization').replace('Bearer ', '');
        const decoded = jwt.verify(token, process.env.JWT_SECRET || 'culturalconnect-secret');
        const user = await User.findById(decoded.userId);

        if (!user) {
            throw new Error();
        }

        req.user = user;
        req.token = token;
        next();
    } catch (error) {
        res.status(401).json({ error: 'Please authenticate' });
    }
};

// External API Integration for Cultural Data
const fetchCulturalData = async (culture, type) => {
    try {
        // Example integration with external cultural APIs
        const apis = {
            literature: `https://api.example.com/literature/${culture}`,
            music: `https://api.example.com/music/${culture}`,
            visualArts: `https://api.example.com/art/${culture}`,
            film: `https://api.example.com/films/${culture}`
        };

        if (apis[type]) {
            const response = await axios.get(apis[type], {
                headers: { 'Authorization': `Bearer ${process.env.API_KEY}` }
            });
            return response.data;
        }

        return [];
    } catch (error) {
        console.error('Error fetching cultural data:', error);
        return [];
    }
};

// Recommendation Engine
const generateRecommendations = async (userId) => {
    try {
        const user = await User.findById(userId);
        if (!user) return [];

        // Collaborative filtering based on user preferences and interactions
        const similarUsers = await User.find({
            'preferences.cultures': { $in: user.preferences.cultures },
            _id: { $ne: userId }
        }).limit(10);

        let recommendedContent = [];

        // Get content liked by similar users
        for (const similarUser of similarUsers) {
            const userInteractions = similarUser.interactions
                .filter(i => i.interactionType === 'like')
                .slice(0, 5);

            for (const interaction of userInteractions) {
                const content = await CulturalContent.findById(interaction.contentId);
                if (content) {
                    recommendedContent.push(content);
                }
            }
        }

        // Remove duplicates and limit results
        recommendedContent = [...new Map(recommendedContent.map(item => 
            [item['_id'].toString(), item])).values()].slice(0, 20);

        return recommendedContent;
    } catch (error) {
        console.error('Error generating recommendations:', error);
        return [];
    }
};

