            user.preferences.music.length > 0 ||
            user.preferences.visualArts.length > 0 ||
            user.preferences.films.length > 0) {

            const preferenceQuery = {
                $or: [
                    { culture: { $in: user.preferences.cultures } },
                    { category: { $in: [
                        ...user.preferences.literature,
                        ...user.preferences.music,
                        ...user.preferences.visualArts,
                        ...user.preferences.films
                    ] } }
                ]
            };

            contentBasedRecommendations = await CulturalContent.find(preferenceQuery)
                .limit(15)
                .lean();
        }

        // Stage 2: Collaborative filtering with improved similarity
        let collaborativeRecommendations = [];

        // Find users with similar interaction patterns
        const userInteractionTypes = user.interactions.map(i => i.interactionType);
        const similarUsers = await User.aggregate([
            {
                $match: {
                    _id: { $ne: user._id },
                    'interactions.interactionType': { $in: userInteractionTypes }
                }
            },
            {
                $addFields: {
                    similarityScore: {
                        $size: {
                            $setIntersection: [
                                user.preferences.cultures,
                                '$preferences.cultures'
                            ]
                        }
                    }
                }
            },
            { $sort: { similarityScore: -1 } },
            { $limit: 5 }
        ]);

        // Get content from similar users with batch processing
        const similarUserIds = similarUsers.map(u => u._id);
        const similarUserInteractions = await User.aggregate([
            { $match: { _id: { $in: similarUserIds } } },
            { $unwind: '$interactions' },
            { $match: { 'interactions.interactionType': 'like' } },
            { $group: { _id: '$interactions.contentId', count: { $sum: 1 } } },
            { $sort: { count: -1 } },
            { $limit: 20 }
        ]);

        const popularContentIds = similarUserInteractions.map(i => i._id);
        if (popularContentIds.length > 0) {
