import pandas as pd
import numpy as np
import json
import warnings
from typing import Dict, List, Any, Optional, Union
from dataclasses import dataclass, field
from datetime import datetime
import threading
import queue
from enum import Enum

warnings.filterwarnings('ignore')

class MergeType(Enum):
    HORIZONTAL = "horizontal"
    VERTICAL = "vertical"

class DataType(Enum):
    NUMERIC = "numeric"
    CATEGORICAL = "categorical"
    DATETIME = "datetime"
    TEXT = "text"

@dataclass
class DatasetMetadata:
    name: str
    file_path: str
    file_format: str
    shape: tuple
    columns: List[str]
    data_types: Dict[str, DataType]
    missing_values: Dict[str, int]
    created_at: datetime = field(default_factory=datetime.now)
    updated_at: datetime = field(default_factory=datetime.now)

@dataclass
class User:
    id: str
    name: str
    role: str
    is_active: bool = True

@dataclass
class Annotation:
    id: str
    user_id: str
    dataset_name: str
    column: str
    comment: str
    timestamp: datetime = field(default_factory=datetime.now)

class DataProfiler:
    def __init__(self):
        self.summary_stats = {}

    def profile_dataset(self, df: pd.DataFrame, name: str) -> DatasetMetadata:
        data_types = {}
        missing_values = {}

        for col in df.columns:
            if pd.api.types.is_numeric_dtype(df[col]):
                data_types[col] = DataType.NUMERIC
            elif pd.api.types.is_datetime64_any_dtype(df[col]):
                data_types[col] = DataType.DATETIME
            elif df[col].nunique() / len(df) < 0.3:
                data_types[col] = DataType.CATEGORICAL
            else:
                data_types[col] = DataType.TEXT

            missing_values[col] = df[col].isna().sum()

        return DatasetMetadata(
            name=name,
            file_path=f"in_memory:{name}",
            file_format="dataframe",
            shape=df.shape,
            columns=list(df.columns),
            data_types=data_types,
            missing_values=missing_values
        )

    def generate_summary_statistics(self, df: pd.DataFrame) -> Dict[str, Any]:
        summary = {
            "basic_stats": {},
            "missing_values": df.isna().sum().to_dict(),
            "data_types": {col: str(df[col].dtype) for col in df.columns}
        }

        numeric_cols = df.select_dtypes(include=[np.number]).columns
        if len(numeric_cols) > 0:
            summary["basic_stats"] = df[numeric_cols].describe().to_dict()

        return summary

    def detect_outliers(self, df: pd.DataFrame, column: str) -> List[int]:
        if column not in df.columns:
            return []

        if not pd.api.types.is_numeric_dtype(df[column]):
            return []

        Q1 = df[column].quantile(0.25)
        Q3 = df[column].quantile(0.75)
        IQR = Q3 - Q1
        lower_bound = Q1 - 1.5 * IQR
        upper_bound = Q3 + 1.5 * IQR

        outliers = df[(df[column] < lower_bound) | (df[column] > upper_bound)].index.tolist()
        return outliers

class DataMerger:
    def __init__(self):
        self.merge_history = []

    def merge_datasets(self, df1: pd.DataFrame, df2: pd.DataFrame, 
                      merge_type: MergeType, on_columns: Optional[List[str]] = None) -> pd.DataFrame:
        if merge_type == MergeType.HORIZONTAL:
            if on_columns is None:
                common_cols = list(set(df1.columns) & set(df2.columns))
                if common_cols:
                    merged_df = pd.merge(df1, df2, on=common_cols, how='inner')
                else:
                    merged_df = pd.concat([df1, df2], axis=1)
            else:
                merged_df = pd.merge(df1, df2, on=on_columns, how='inner')
        else:
            merged_df = pd.concat([df1, df2], axis=0, ignore_index=True)

        self.merge_history.append({
            'timestamp': datetime.now(),
            'type': merge_type.value,
            'shape_before': (df1.shape, df2.shape),
            'shape_after': merged_df.shape
        })

        return merged_df

    def handle_data_type_inconsistencies(self, df: pd.DataFrame) -> pd.DataFrame:
        df_copy = df.copy()

        for col in df_copy.columns:
            if df_copy[col].dtype == 'object':
                try:
                    df_copy[col] = pd.to_numeric(df_copy[col], errors='ignore')
                except:
                    try:
                        df_copy[col] = pd.to_datetime(df_copy[col], errors='ignore')
                    except:
                        pass

        return df_copy

class CorrelationAnalyzer:
    def __init__(self):
        self.correlation_results = {}

    def calculate_correlations(self, df: pd.DataFrame, method: str = 'pearson') -> pd.DataFrame:
        numeric_cols = df.select_dtypes(include=[np.number]).columns

        if len(numeric_cols) < 2:
            return pd.DataFrame()

        if method == 'pearson':
            correlation_matrix = df[numeric_cols].corr(method='pearson')
        elif method == 'spearman':
            correlation_matrix = df[numeric_cols].corr(method='spearman')
        else:
            correlation_matrix = df[numeric_cols].corr()

        self.correlation_results[method] = correlation_matrix
        return correlation_matrix

    def get_correlation_pairs(self, df: pd.DataFrame, threshold: float = 0.7) -> List[Dict[str, Any]]:
        correlation_matrix = self.calculate_correlations(df)

        if correlation_matrix.empty:
            return []

        pairs = []
        columns = correlation_matrix.columns

        for i in range(len(columns)):
            for j in range(i+1, len(columns)):
                corr_value = correlation_matrix.iloc[i, j]
                if abs(corr_value) >= threshold:
                    pairs.append({
                        'variable1': columns[i],
                        'variable2': columns[j],
                        'correlation': corr_value,
                        'strength': 'strong' if abs(corr_value) >= 0.8 else 'moderate'
                    })

        return pairs

class CollaborationManager:
    def __init__(self):
        self.active_users = {}
        self.annotations = []
        self.comments = []
        self.update_queue = queue.Queue()
        self.lock = threading.Lock()

    def add_user(self, user: User):
        with self.lock:
            self.active_users[user.id] = user

    def remove_user(self, user_id: str):
        with self.lock:
            if user_id in self.active_users:
                del self.active_users[user_id]

    def add_annotation(self, annotation: Annotation):
        with self.lock:
            self.annotations.append(annotation)
            self.update_queue.put({
                'type': 'annotation',
                'data': annotation,
                'timestamp': datetime.now()
            })

    def get_dataset_annotations(self, dataset_name: str) -> List[Annotation]:
        return [ann for ann in self.annotations if ann.dataset_name == dataset_name]

    def get_real_time_updates(self):
        updates = []
        while not self.update_queue.empty():
            updates.append(self.update_queue.get())

