        return pd.read_json(file_path, **kwargs)

    @classmethod
    def import_dataset(cls, file_path: str, format_hint: Optional[str] = None) -> pd.DataFrame:
        """Import dataset based on file extension or format hint."""
        if format_hint:
            format_hint = format_hint.lower()

        ext = os.path.splitext(file_path)[1].lower()

        if format_hint == 'csv' or ext == '.csv':
            return cls.import_csv(file_path)
        elif format_hint in ['xlsx', 'xls'] or ext in ['.xlsx', '.xls']:
            return cls.import_excel(file_path)
        elif format_hint == 'json' or ext == '.json':
