    def ingest(self, data_source: DataSource) -> pd.DataFrame:
        """
        Ingest data from the provided data source

        Args:
            data_source: DataSource object (CSV, Excel, or Database)

        Returns:
            pandas DataFrame containing the ingested data
        """
        logger.info("Starting data ingestion...")

