            logger.info("Data validation passed successfully")
        else:
            logger.warning(f"Data validation found {len(self.issues)} issues")

        return self.validation_results['passed']

    def _get_default_rules(self, data: pd.DataFrame) -> Dict[str, Any]:
        """Generate default validation rules based on data"""
        rules = {
            'required_columns': list(data.columns),
            'numeric_columns': list(data.select_dtypes(include=[np.number]).columns),
            'date_columns': list(data.select_dtypes(include=['datetime']).columns),
            'max_missing_percentage': 0.1,  # Allow up to 10% missing values
            'unique_constraints': [],  # Columns that should be unique
        }
        return rules

    def _check_completeness(self, data: pd.DataFrame, rules: Dict[str, Any]):
        """Check for missing values and required columns"""
        # Check required columns
        missing_columns = set(rules.get('required_columns', [])) - set(data.columns)
        if missing_columns:
            self.issues.append(f"Completeness: Missing required columns: {missing_columns}")

        # Check for excessive missing values
        max_missing = rules.get('max_missing_percentage', 0.1)
        for column in data.columns:
            missing_pct = data[column].isnull().mean()
            if missing_pct > max_missing:
                self.issues.append(f"Completeness: Column '{column}' has {missing_pct:.1%} missing values (threshold: {max_missing:.1%})")

    def _check_consistency(self, data: pd.DataFrame, rules: Dict[str, Any]):
        """Check data consistency"""
        # Check for duplicate rows
        duplicates = data.duplicated().sum()
        if duplicates > 0:
            self.issues.append(f"Consistency: Found {duplicates} duplicate rows")

        # Check data type consistency
        for column in data.columns:
            if data[column].dtype == 'object':
                # Check for mixed types in object columns
                unique_types = set(type(x) for x in data[column].dropna())
                if len(unique_types) > 1:
                    self.issues.append(f"Consistency: Column '{column}' has mixed data types: {unique_types}")

    def _check_validity(self, data: pd.DataFrame, rules: Dict[str, Any]):
        """Check data validity against business rules"""
        # Check numeric columns for invalid values (e.g., negative where not allowed)
        numeric_cols = rules.get('numeric_columns', [])
        for column in numeric_cols:
            if column in data.columns:
                # Example: Check for negative values in positive-only columns
                if (data[column] < 0).any():
                    self.issues.append(f"Validity: Column '{column}' contains negative values")

        # Check unique constraints
        unique_cols = rules.get('unique_constraints', [])
        for column in unique_cols:
            if column in data.columns:
                duplicates = data[column].duplicated().sum()
                if duplicates > 0:
                    self.issues.append(f"Validity: Column '{column}' should be unique but has {duplicates} duplicates")

    def _check_accuracy(self, data: pd.DataFrame, rules: Dict[str, Any]):
        """Check data accuracy (example checks)"""
        # Example: Check date ranges
        date_cols = rules.get('date_columns', [])
        for column in date_cols:
            if column in data.columns:
                if data[column].max() > pd.Timestamp.now():
                    self.issues.append(f"Accuracy: Column '{column}' has future dates")

        # Example: Check for outliers in numeric columns
        numeric_cols = rules.get('numeric_columns', [])
        for column in numeric_cols:
            if column in data.columns:
                q1 = data[column].quantile(0.25)
                q3 = data[column].quantile(0.75)
                iqr = q3 - q1
                outliers = ((data[column] < (q1 - 1.5 * iqr)) | (data[column] > (q3 + 1.5 * iqr))).sum()
                if outliers > 0:
