class ComplexityLevel(Enum):
    """Enum for code complexity levels."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    VERY_HIGH = "very_high"

class CodeComplexityModule(Module):
    """
    Analyzes code complexity using metrics like cyclomatic complexity,
    nesting depth, and code duplication. Generates interactive visualizations.
    """

    def __init__(self):
        super().__init__("Code Complexity Visualization Module")
        self.complexity_data = {}
        self.duplication_data = {}

    def analyze(self, source_code: str, file_path: str = "") -> Dict:
        """
        Analyze code complexity metrics.

        Args:
            source_code: The source code to analyze
            file_path: Path to the source file

        Returns:
            Dictionary containing complexity metrics
        """
        try:
            tree = ast.parse(source_code)

            # Calculate various complexity metrics
            cyclomatic_complexity = self._calculate_cyclomatic_complexity(tree)
            nesting_depth = self._calculate_nesting_depth(tree)
            function_count = self._count_functions(tree)
            class_count = self._count_classes(tree)
            line_count = len(source_code.split('\n'))

            # Detect code duplication
            duplication_info = self._detect_duplication(source_code, file_path)

            # Determine complexity level
            complexity_level = self._determine_complexity_level(
                cyclomatic_complexity, nesting_depth
            )

            # Generate recommendations
            recommendations = self._generate_recommendations(
                cyclomatic_complexity, nesting_depth, duplication_info
            )

            result = {
                "file_path": file_path,
                "cyclomatic_complexity": cyclomatic_complexity,
                "nesting_depth": nesting_depth,
                "function_count": function_count,
                "class_count": class_count,
                "line_count": line_count,
                "complexity_level": complexity_level.value,
                "duplication": duplication_info,
                "recommendations": recommendations,
                "visualization_data": self._generate_visualization_data(
                    tree, cyclomatic_complexity, nesting_depth
                )
            }

            self.complexity_data[file_path] = result
            return result

        except SyntaxError as e:
            return {
                "file_path": file_path,
                "error": f"Syntax error: {str(e)}",
                "complexity_level": ComplexityLevel.HIGH.value
            }

    def _calculate_cyclomatic_complexity(self, tree: ast.AST) -> int:
        """Calculate cyclomatic complexity of the code."""
        complexity = 1  # Base complexity

        for node in ast.walk(tree):
            if isinstance(node, (ast.If, ast.While, ast.For, ast.AsyncFor,
                               ast.Try, ast.ExceptHandler, ast.With, ast.AsyncWith)):
                complexity += 1
            elif isinstance(node, (ast.BoolOp, ast.Compare)):
                complexity += len(node.ops) - 1

        return complexity

    def _calculate_nesting_depth(self, tree: ast.AST) -> int:
        """Calculate maximum nesting depth in the code."""
        max_depth = 0
        current_depth = 0

        def visit_node(node):
            nonlocal current_depth, max_depth

            if isinstance(node, (ast.If, ast.While, ast.For, ast.AsyncFor,
                               ast.Try, ast.With, ast.AsyncWith,
                               ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                current_depth += 1
                max_depth = max(max_depth, current_depth)

                # Recursively visit child nodes
                for child in ast.iter_child_nodes(node):
                    visit_node(child)

                current_depth -= 1
            else:
                for child in ast.iter_child_nodes(node):
                    visit_node(child)

        visit_node(tree)
        return max_depth

    def _count_functions(self, tree: ast.AST) -> int:
        """Count number of function definitions."""
        return sum(1 for node in ast.walk(tree) 
                  if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)))

    def _count_classes(self, tree: ast.AST) -> int:
        """Count number of class definitions."""
        return sum(1 for node in ast.walk(tree) if isinstance(node, ast.ClassDef))

    def _detect_duplication(self, source_code: str, file_path: str) -> Dict:
        """Detect code duplication within the file."""
        lines = source_code.strip().split('\n')
        significant_lines = [line.strip() for line in lines if line.strip()]

        # Simple duplication detection by looking for repeated lines
        line_counts = Counter(significant_lines)
        duplicate_lines = {line: count for line, count in line_counts.items() 
                          if count > 1 and len(line) > 20}

        return {
            "duplicate_line_count": len(duplicate_lines),
            "duplicate_ratio": len(duplicate_lines) / len(significant_lines) 
                              if significant_lines else 0,
            "examples": list(duplicate_lines.keys())[:3]
        }

    def _determine_complexity_level(self, cyclomatic: int, nesting: int) -> ComplexityLevel:
        """Determine overall complexity level based on metrics."""
        score = cyclomatic * 0.7 + nesting * 0.3

        if score < 5:
            return ComplexityLevel.LOW
        elif score < 10:
            return ComplexityLevel.MEDIUM
        elif score < 20:
            return ComplexityLevel.HIGH
        else:
            return ComplexityLevel.VERY_HIGH

    def _generate_recommendations(self, cyclomatic: int, nesting: int, 
                                 duplication: Dict) -> List[str]:
        """Generate optimization recommendations based on complexity metrics."""
        recommendations = []

        if cyclomatic > 10:
            recommendations.append(
                "Consider refactoring complex functions into smaller, single-purpose functions."
            )

        if nesting > 3:
            recommendations.append(
                "Reduce nesting depth by using early returns or extracting nested logic."
            )

        if duplication["duplicate_ratio"] > 0.1:
            recommendations.append(
                "Extract duplicated code into reusable functions or classes."
            )

        if cyclomatic > 15 or nesting > 4:
            recommendations.append(
                "Review code for potential simplification opportunities."
            )

        if not recommendations:
            recommendations.append("Code complexity is well-managed. Keep up the good work!")

        return recommendations

    def _generate_visualization_data(self, tree: ast.AST, cyclomatic: int, 
                                    nesting: int) -> Dict:
        """Generate data for complexity visualization."""
        visualization = {
            "hierarchy": self._extract_code_hierarchy(tree),
            "metrics": {
                "cyclomatic_complexity": cyclomatic,
                "nesting_depth": nesting,
                "function_density": self._calculate_function_density(tree)
            },
            "hotspots": self._identify_complexity_hotspots(tree)
        }
        return visualization

    def _extract_code_hierarchy(self, tree: ast.AST) -> List[Dict]:
        """Extract code structure hierarchy."""
        hierarchy = []

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                hierarchy.append({
                    "type": type(node).__name__,
                    "name": node.name,
                    "line": node.lineno if hasattr(node, 'lineno') else 0,
                    "complexity": self._calculate_cyclomatic_complexity(node)
                })

        return hierarchy

    def _calculate_function_density(self, tree: ast.AST) -> float:
        """Calculate function density (functions per 100 lines)."""
        functions = sum(1 for node in ast.walk(tree) 
                       if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)))
        lines = sum(1 for _ in ast.walk(tree))
        return (functions / lines * 100) if lines > 0 else 0

    def _identify_complexity_hotspots(self, tree: ast.AST) -> List[Dict]:
        """Identify areas of high complexity."""
        hotspots = []

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                complexity = self._calculate_cyclomatic_complexity(node)
                if complexity > 5:
                    hotspots.append({
                        "name": node.name,
                        "complexity": complexity,
                        "line": node.lineno if hasattr(node, 'lineno') else 0
                    })

        return sorted(hotspots, key=lambda x: x["complexity"], reverse=True)[:5]

