            recommendations = self._generate_recommendations(
                cyclomatic_complexity, nesting_depth, duplication_info
            )

            result = {
                "file_path": file_path,
                "cyclomatic_complexity": cyclomatic_complexity,
                "nesting_depth": nesting_depth,
                "function_count": function_count,
                "class_count": class_count,
                "line_count": line_count,
                "complexity_level": complexity_level.value,
                "duplication": duplication_info,
                "recommendations": recommendations,
                "visualization_data": self._generate_visualization_data(
                    tree, cyclomatic_complexity, nesting_depth
                )
            }

            self.complexity_data[file_path] = result
            return result

        except SyntaxError as e:
            return {
                "file_path": file_path,
                "error": f"Syntax error: {str(e)}",
                "complexity_level": ComplexityLevel.HIGH.value
            }

    def _calculate_cyclomatic_complexity(self, tree: ast.AST) -> int:
        """Calculate cyclomatic complexity of the code."""
        complexity = 1  # Base complexity

        for node in ast.walk(tree):
            if isinstance(node, (ast.If, ast.While, ast.For, ast.AsyncFor,
                               ast.Try, ast.ExceptHandler, ast.With, ast.AsyncWith)):
                complexity += 1
            elif isinstance(node, (ast.BoolOp, ast.Compare)):
                complexity += len(node.ops) - 1

        return complexity

    def _calculate_nesting_depth(self, tree: ast.AST) -> int:
        """Calculate maximum nesting depth in the code."""
        max_depth = 0
        current_depth = 0

        def visit_node(node):
            nonlocal current_depth, max_depth

            if isinstance(node, (ast.If, ast.While, ast.For, ast.AsyncFor,
                               ast.Try, ast.With, ast.AsyncWith,
                               ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                current_depth += 1
                max_depth = max(max_depth, current_depth)

                # Recursively visit child nodes
                for child in ast.iter_child_nodes(node):
                    visit_node(child)

                current_depth -= 1
            else:
                for child in ast.iter_child_nodes(node):
                    visit_node(child)

        visit_node(tree)
        return max_depth

    def _count_functions(self, tree: ast.AST) -> int:
        """Count number of function definitions."""
        return sum(1 for node in ast.walk(tree) 
                  if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)))

    def _count_classes(self, tree: ast.AST) -> int:
        """Count number of class definitions."""
        return sum(1 for node in ast.walk(tree) if isinstance(node, ast.ClassDef))

    def _detect_duplication(self, source_code: str, file_path: str) -> Dict:
        """Detect code duplication within the file."""
        lines = source_code.strip().split('\n')
        significant_lines = [line.strip() for line in lines if line.strip()]

        # Simple duplication detection by looking for repeated lines
        line_counts = Counter(significant_lines)
        duplicate_lines = {line: count for line, count in line_counts.items() 
                          if count > 1 and len(line) > 20}

        return {
            "duplicate_line_count": len(duplicate_lines),
            "duplicate_ratio": len(duplicate_lines) / len(significant_lines) 
                              if significant_lines else 0,
            "examples": list(duplicate_lines.keys())[:3]
        }

    def _determine_complexity_level(self, cyclomatic: int, nesting: int) -> ComplexityLevel:
        """Determine overall complexity level based on metrics."""
        score = cyclomatic * 0.7 + nesting * 0.3

        if score < 5:
            return ComplexityLevel.LOW
        elif score < 10:
            return ComplexityLevel.MEDIUM
        elif score < 20:
            return ComplexityLevel.HIGH
        else:
            return ComplexityLevel.VERY_HIGH

    def _generate_recommendations(self, cyclomatic: int, nesting: int, 
                                 duplication: Dict) -> List[str]:
        """Generate optimization recommendations based on complexity metrics."""
        recommendations = []

        if cyclomatic > 10:
            recommendations.append(
                "Consider refactoring complex functions into smaller, single-purpose functions."
            )

        if nesting > 3:
