                "Reduce nesting depth by using early returns or extracting nested logic."
            )

        if duplication["duplicate_ratio"] > 0.1:
            recommendations.append(
                "Extract duplicated code into reusable functions or classes."
            )

        if cyclomatic > 15 or nesting > 4:
            recommendations.append(
                "Review code for potential simplification opportunities."
            )

        if not recommendations:
            recommendations.append("Code complexity is well-managed. Keep up the good work!")

        return recommendations

    def _generate_visualization_data(self, tree: ast.AST, cyclomatic: int, 
                                    nesting: int) -> Dict:
        """Generate data for complexity visualization."""
        visualization = {
