                "nesting_depth": nesting,
                "function_density": self._calculate_function_density(tree)
            },
            "hotspots": self._identify_complexity_hotspots(tree)
        }
        return visualization

    def _extract_code_hierarchy(self, tree: ast.AST) -> List[Dict]:
        """Extract code structure hierarchy."""
        hierarchy = []

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                hierarchy.append({
                    "type": type(node).__name__,
                    "name": node.name,
                    "line": node.lineno if hasattr(node, 'lineno') else 0,
                    "complexity": self._calculate_cyclomatic_complexity(node)
                })

        return hierarchy

    def _calculate_function_density(self, tree: ast.AST) -> float:
        """Calculate function density (functions per 100 lines)."""
        functions = sum(1 for node in ast.walk(tree) 
                       if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)))
        lines = sum(1 for _ in ast.walk(tree))
        return (functions / lines * 100) if lines > 0 else 0

    def _identify_complexity_hotspots(self, tree: ast.AST) -> List[Dict]:
        """Identify areas of high complexity."""
        hotspots = []

        for node in ast.walk(tree):
