            'id': story_id,
            'title': title,
            'description': description,
            'author': author_username,
            'created_at': datetime.now().isoformat(),
            'updated_at': datetime.now().isoformat(),
            'chapters': [],
            'collaborators': [author_username],
            'is_completed': False,
            'current_version': 1
        }

        story_file = os.path.join(self.stories_dir, f"{story_id}.json")
        with open(story_file, 'w') as f:
            json.dump(story_data, f, indent=2)

        # Create initial version
        self._save_version(story_id, story_data, 1)

        return story_id, story_data

    def get_story(self, story_id):
        story_file = os.path.join(self.stories_dir, f"{story_id}.json")
        if os.path.exists(story_file):
            with open(story_file, 'r') as f:
                return json.load(f)
        return None

    def add_chapter(self, story_id, chapter_title, content, author_username):
        story = self.get_story(story_id)
        if not story:
            return False, "Story not found"

        if author_username not in story['collaborators']:
            return False, "User is not a collaborator"

        chapter_id = len(story['chapters']) + 1
        chapter = {
            'id': chapter_id,
            'title': chapter_title,
            'content': content,
            'author': author_username,
            'created_at': datetime.now().isoformat(),
            'version': 1
        }

        story['chapters'].append(chapter)
        story['updated_at'] = datetime.now().isoformat()
        story['current_version'] += 1

        self._save_story(story)
        self._save_version(story_id, story, story['current_version'])

        return True, "Chapter added successfully"

    def edit_chapter(self, story_id, chapter_id, new_content, author_username):
        story = self.get_story(story_id)
        if not story:
            return False, "Story not found"

        if author_username not in story['collaborators']:
            return False, "User is not a collaborator"

        for chapter in story['chapters']:
            if chapter['id'] == chapter_id:
                chapter['content'] = new_content
                chapter['last_edited'] = datetime.now().isoformat()
                chapter['version'] += 1
                story['updated_at'] = datetime.now().isoformat()
                story['current_version'] += 1

                self._save_story(story)
                self._save_version(story_id, story, story['current_version'])
                return True, "Chapter updated successfully"

