# WebSocket Manager for Real-time Communication
class WebSocketManager:
    """Manages WebSocket connections for real-time updates"""

    def __init__(self):
        self.connections: Dict[str, Set] = {}  # room_id -> set of connections
        self.user_connections: Dict[str, Set] = {}  # user_id -> set of connections

    async def connect(self, websocket, room_id: str, user_id: str):
        """Handle new WebSocket connection"""
        if room_id not in self.connections:
            self.connections[room_id] = set()
        if user_id not in self.user_connections:
            self.user_connections[user_id] = set()

        self.connections[room_id].add(websocket)
        self.user_connections[user_id].add(websocket)

    async def disconnect(self, websocket, room_id: str, user_id: str):
        """Handle WebSocket disconnection"""
        if room_id in self.connections:
            self.connections[room_id].discard(websocket)
        if user_id in self.user_connections:
            self.user_connections[user_id].discard(websocket)

    async def broadcast_to_room(self, room_id: str, message: Dict):
        """Broadcast message to all connections in a room"""
        if room_id in self.connections:
            for connection in self.connections[room_id]:
                try:
                    await connection.send_json(message)
                except:
                    pass

    async def send_to_user(self, user_id: str, message: Dict):
        """Send message to specific user"""
        if user_id in self.user_connections:
            for connection in self.user_connections[user_id]:
                try:
                    await connection.send_json(message)
                except:
                    pass

