            name=name,
            creator_id=creator_id,
            created_at=datetime.now(),
            is_public=is_public,
            max_users=max_users
        )

        self.db.add_room(room)
        return room_id

    def join_room(self, room_id: str, user_id: str) -> bool:
        """Add user to a room"""
        if room_id not in self.db.rooms:
            return False

        room = self.db.rooms[room_id]

        if len(room.current_users) >= room.max_users:
            return False

        room.current_users.add(user_id)

        # Notify room about new user
        asyncio.create_task(
            self.ws_manager.broadcast_to_room(
                room_id,
                {
                    'type': 'user_joined',
                    'user_id': user_id,
                    'timestamp': datetime.now().isoformat()
                }
            )
        )

        return True

    def leave_room(self, room_id: str, user_id: str) -> bool:
        """Remove user from a room"""
        if room_id not in self.db.rooms:
            return False

        room = self.db.rooms[room_id]
        room.current_users.discard(user_id)

        # Notify room about user leaving
        asyncio.create_task(
            self.ws_manager.broadcast_to_room(
                room_id,
                {
                    'type': 'user_left',
                    'user_id': user_id,
                    'timestamp': datetime.now().isoformat()
                }
            )
        )

        return True

