    def vote_for_mashup(self, user_id: str, mashup_id: str, score: int) -> bool:
        """Vote for a mashup (score 1-5)"""
        # Check if user already voted
        for vote in self.db.votes.values():
            if vote.user_id == user_id and vote.mashup_id == mashup_id:
                return False

        if score < 1 or score > 5:
