        if quest.id in self.quests:
            return False
        self.quests[quest.id] = quest
        return True

    def get_quest(self, quest_id: str) -> Optional[Quest]:
        return self.quests.get(quest_id)

    def get_quests_by_subject(self, subject: str) -> List[Quest]:
        return [q for q in self.quests.values() if q.subject == subject]

    # Progress operations
    def update_progress(self, progress: UserProgress) -> bool:
        self.progress[progress.id] = progress
        return True

    def get_user_progress(self, user_id: str) -> List[UserProgress]:
        return [p for p in self.progress.values() if p.user_id == user_id]

    # Backup and recovery simulation
    def backup(self) -> Dict:
        return {
            'users': {uid: user.to_dict() for uid, user in self.users.items()},
            'families': {fid: family.to_dict() for fid, family in self.families.items()},
            'quests': {qid: quest.to_dict() for qid, quest in self.quests.items()},
            'progress': {pid: prog.to_dict() for pid, prog in self.progress.items()}
