from abc import ABC, abstractmethod
from dataclasses import dataclass, asdict
from typing import List, Dict, Optional, Any
from enum import Enum

# ===== DATABASE LAYER =====
# database.py

class Database(ABC):
    """Abstract base class for database operations"""

    @abstractmethod
    def create(self, collection: str, data: dict) -> str:
        pass

    @abstractmethod
    def read(self, collection: str, query: dict) -> List[dict]:
        pass

    @abstractmethod
    def update(self, collection: str, query: dict, data: dict) -> bool:
        pass

    @abstractmethod
    def delete(self, collection: str, query: dict) -> bool:
        pass


class InMemoryDatabase(Database):
    """In-memory database implementation for development"""

    def __init__(self):
        self.data = {
            'users': {},
            'families': {},
            'quests': {},
            'progress': {},
            'achievements': {}
        }

    def create(self, collection: str, data: dict) -> str:
        if collection not in self.data:
            self.data[collection] = {}

        item_id = str(uuid.uuid4())
        data['id'] = item_id
        data['created_at'] = datetime.datetime.now().isoformat()
        self.data[collection][item_id] = data.copy()
        return item_id

    def read(self, collection: str, query: dict) -> List[dict]:
        if collection not in self.data:
            return []

        results = []
        for item in self.data[collection].values():
            match = True
            for key, value in query.items():
                if item.get(key) != value:
                    match = False
                    break
            if match:
                results.append(item.copy())
        return results

    def update(self, collection: str, query: dict, data: dict) -> bool:
        if collection not in self.data:
            return False

        updated = False
        for item_id, item in self.data[collection].items():
            match = True
            for key, value in query.items():
                if item.get(key) != value:
                    match = False
                    break
            if match:
                item.update(data)
                item['updated_at'] = datetime.datetime.now().isoformat()
                updated = True
        return updated

    def delete(self, collection: str, query: dict) -> bool:
        if collection not in self.data:
            return False

        deleted = False
        ids_to_delete = []
        for item_id, item in self.data[collection].items():
            match = True
            for key, value in query.items():
                if item.get(key) != value:
                    match = False
                    break
            if match:
                ids_to_delete.append(item_id)
                deleted = True

        for item_id in ids_to_delete:
            del self.data[collection][item_id]
        return deleted


