import secrets
import threading
import time
import asyncio
from abc import ABC, abstractmethod
from collections import defaultdict
import logging

# ==================== Data Models ====================

class NotificationType(Enum):
    """Types of notifications that can be sent to users."""
    DEADLINE_REMINDER = "deadline_reminder"
    MILESTONE_REACHED = "milestone_reached"
    CONTRIBUTION_MADE = "contribution_made"
    BUDGET_ALERT = "budget_alert"
    GROUP_INVITATION = "group_invitation"
    GOAL_COMPLETED = "goal_completed"
    CHAT_MESSAGE = "chat_message"


@dataclass
class User:
    """Represents a user in the system."""
    user_id: str
    username: str
    email: str
    password_hash: str
    salt: str
    created_at: datetime.datetime
    groups: List[str] = field(default_factory=list)  # Group IDs the user belongs to
    notifications: List[Dict] = field(default_factory=list)

    def verify_password(self, password: str) -> bool:
        """Verify if the provided password matches the stored hash."""
        hash_obj = hashlib.sha256()
        hash_obj.update((password + self.salt).encode('utf-8'))
        return hash_obj.hexdigest() == self.password_hash


@dataclass
class FinancialGoal:
    """Represents a financial goal for a group."""
    goal_id: str
    group_id: str
    name: str
    description: str
    target_amount: float
    current_amount: float = 0.0
    deadline: datetime.datetime
    created_at: datetime.datetime
    created_by: str  # User ID
    milestones: List[Dict] = field(default_factory=list)
    contributions: Dict[str, float] = field(default_factory=dict)  # user_id -> amount

    def add_contribution(self, user_id: str, amount: float) -> bool:
        """Add a contribution to the goal."""
        if amount <= 0:
            return False

        self.current_amount += amount
        if user_id in self.contributions:
            self.contributions[user_id] += amount
        else:
            self.contributions[user_id] = amount
        return True

    def get_progress_percentage(self) -> float:
        """Get the progress percentage towards the goal."""
        if self.target_amount == 0:
            return 0.0
        return (self.current_amount / self.target_amount) * 100

    def is_completed(self) -> bool:
        """Check if the goal has been completed."""
        return self.current_amount >= self.target_amount

    def get_days_remaining(self) -> int:
        """Get the number of days remaining until the deadline."""
        now = datetime.datetime.now()
        delta = self.deadline - now
        return max(0, delta.days)


@dataclass
class Group:
    """Represents a group of users collaborating on financial goals."""
    group_id: str
    name: str
    description: str
    created_by: str  # User ID
    created_at: datetime.datetime
    members: List[str] = field(default_factory=list)  # User IDs
    goals: List[str] = field(default_factory=list)  # Goal IDs
    chat_messages: List[Dict] = field(default_factory=list)

    def add_member(self, user_id: str) -> bool:
        """Add a member to the group."""
        if user_id not in self.members:
            self.members.append(user_id)
            return True
        return False

    def remove_member(self, user_id: str) -> bool:
        """Remove a member from the group."""
        if user_id in self.members:
            self.members.remove(user_id)
            return True
        return False

    def is_member(self, user_id: str) -> bool:
        """Check if a user is a member of the group."""
        return user_id in self.members


@dataclass
