atetime.now()\n                \n        elif update_type == \"user_joined\":\n            user_id = update_data[\"user_id\"]\n            if user_id not in self.state.active_users:\n                self.state.active_users.add(user_id)\n                \n        elif update_type == \"user_left\":\n            user_id = update_data[\"user_id\"]\n            if user_id in self.state.active_users:\n                self.state.active_users.remove(user_id)\n                \n        elif update_type == \"texture_applied\":\n            element_id = update_data[\"element_id\"]\n            texture_name = update_data[\"texture\"]\n            \n            if element_id in self.state.elements:\n                element = self.state.elements[element_id]\n                self.shape_tool.apply_texture(element.shape, texture_name)\n                self.state.modified_at = datetime.now()\n                \n        elif update_type == \"annotation_added\":\n            # Handle remote annotation addition\n            element_id = update_data[\"element_id\"]\n            user_id = update_data[\"user_id\"]\n            text = update_data[\"text\"]\n            position = tuple(update_data[\"position\"])\n            \n            if element_id in self.state.elements:\n                self.annotation_system.add_annotation(\n                    element_id, user_id, text, position\n                )\n                self.state.modified_at = datetime.now()"
